const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";

const load = async f => { try { return JSON.parse(await fs.readFile(S+"\\"+f,"utf8")); } catch { return []; } };
const [q, pool, sus, fin, rest] = await Promise.all([
  load("_QUEUE_RESULT.json"), load("_POOL_PROBE.json"), load("_SUSPECTS_RESULT.json"),
  load("_FINAL_RESULT.json"), load("_REST_RESULT.json")
]);
const all = [...pool,...q,...sus,...fin,...rest];
const good = all.filter(o=>o.verdict==="职位+金额"||o.verdict==="职位列表");

// 项目/任务类关键词（排除纯职位板）
const GIG = /(freelanc|gig|task|bounty|outsourc|marketplace|hire|contract|microtask|transcri|tutor|design.*contest|写|接单|悬赏|众包|兼职|外包)/i;
const JOBONLY = /(career|recruit|job-board|jobboard|hiring|vacancy)/i;

const cands = good.filter(o => {
  const h = String(o.host||""); const c = String(o.cat||"");
  return GIG.test(h) || GIG.test(c) || /接单|赏金|数字商品/.test(c);
}).filter(o => !JOBONLY.test(String(o.host)));

const list = cands.map(o=>({host:o.host, cat:o.cat||"", jobs:o.jobHits||0, money:o.moneyHits||0}))
  .sort((a,b)=>b.jobs-a.jobs);

await fs.writeFile(S+"\\_GIG_POOL.json", JSON.stringify(list,null,1), "utf8");
return { poolSize: list.length, top30: list.slice(0,30) };
